package com.agritech.service;import com.agritech.model.ProfitEstimate;import java.math.*;public class ProfitService{public ProfitEstimate calculate(double acres,double yieldPerAcre,BigDecimal price,BigDecimal costPerAcre){if(acres<=0||yieldPerAcre<=0||price.signum()<0||costPerAcre.signum()<0)throw new IllegalArgumentException("Area, yield, price and cost must be valid positive values.");BigDecimal a=BigDecimal.valueOf(acres),revenue=BigDecimal.valueOf(yieldPerAcre).multiply(a).multiply(price).setScale(2,RoundingMode.HALF_UP),cost=costPerAcre.multiply(a).setScale(2,RoundingMode.HALF_UP),profit=revenue.subtract(cost);return new ProfitEstimate(revenue,cost,profit,profit.divide(a,2,RoundingMode.HALF_UP));}}
